.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: 1rem;
}
.gallery img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }
